using System;

public class Person {
    public string Name { get; set; }
    public int Age;
}

public class C {
    public void M(Person p) {
        switch (p) {
            case Person { Name: var name, Age: 0}:
                Console.WriteLine($"Hello baby { name }!");
            break;
            case Person { Name: var name }:
                Console.WriteLine($"Hello { name }!");
            break;
        }
    }
}
